awk -F, '$1=="alpha_sweep" && ($3=="0.0" || $3=="0.25" || $3=="0.5" || $3=="0.75" || $3=="1.0") && $5=="10" {
  alpha=$3;
  naive_rate=$21;
  diff_rate=$22;
  threshold_rate=$23;
  permg_rate=$24;
  ty_rate=$25;

  # Convert to percentage
  naive_pct=naive_rate*100;
  diff_pct=diff_rate*100;
  thresh_pct=threshold_rate*100;
  permg_pct=permg_rate*100;
  ty_pct=ty_rate*100;

  print alpha, naive_pct, diff_pct, thresh_pct, permg_pct, ty_pct;
}' /home/ubuntu/.agent-ml-research-idea_gen_0514_4/projects/distrib_canary_collapse/artifacts/dose_response_d120_recompiled.csv | 
awk '{
  alpha=$1;
  naive[alpha]+=$2; diff[alpha]+=$3; thresh[alpha]+=$4; permg[alpha]+=$5; ty[alpha]+=$6;
  count[alpha]++;
}
END {
  for(a in count) {
    printf("Alpha=%.2f: NaiveXCorr=%.1f DiffXCorr=%.1f Threshold=%.1f PermG=%.1f TY=%.1f (n=%d)\n", 
      a, naive[a]/count[a], diff[a]/count[a], thresh[a]/count[a], permg[a]/count[a], ty[a]/count[a], count[a]);
  }
}' | sort -V

